// assets/panel-v2.js — Session Insight v2 前端（独立于 v1，路由 /page?v=2）
const PROTOCOL = "hana.plugin.ui";
const VERSION = 1;
let seq = 0;
function targetOrigin(){const p=new URLSearchParams(window.location.search);const e=p.get("hana-host-origin");if(e)return e;try{return new URL(document.referrer).origin;}catch{return "*";}}
function post(m){window.parent.postMessage(m,targetOrigin());}
function event(type,payload){post({protocol:PROTOCOL,version:VERSION,kind:"event",type,payload});}
function request(type,payload,timeoutMs=10000){const id=`hana-plugin-${Date.now()}-${++seq}`;const origin=targetOrigin();return new Promise((resolve,reject)=>{const t=window.setTimeout(()=>{window.removeEventListener("message",onM);reject(new Error(`Host request timed out: ${type}`));},timeoutMs);function onM(evt){if(evt.source!==window.parent)return;if(origin!=="*"&&evt.origin!==origin)return;const m=evt.data||{};if(m.protocol!==PROTOCOL||m.version!==VERSION||m.id!==id||m.type!==type)return;window.clearTimeout(t);window.removeEventListener("message",onM);if(m.kind==="error")reject(new Error(m.error?.message||`Host request failed: ${type}`));else resolve(m.payload);}window.addEventListener("message",onM);post({protocol:PROTOCOL,version:VERSION,id,kind:"request",type,payload});});}
function currentPluginId(){const m=/^\/api\/plugins\/([^/]+)(?:\/|$)/.exec(window.location.pathname||"");if(!m)throw new Error("Plugin API helper requires an iframe route under /api/plugins/:pluginId/.");return decodeURIComponent(m[1]);}
function normalizePluginApiPath(input){if(typeof input!=="string"||!input.trim())throw new Error("Invalid plugin API path.");const t=input.trim();if(t.includes("\\")||t.includes("\0")||t.includes("#")||t.startsWith("//")||/^[a-z][a-z0-9+.-]*:/i.test(t))throw new Error("Invalid plugin API path.");const s=t.replace(/^\/+/, "");if(!s||s.startsWith("./")||s==="api/plugins"||s.startsWith("api/plugins/"))throw new Error("Invalid plugin API path.");const q=s.indexOf("?");const raw=q>=0?s.slice(0,q):s;for(const seg of raw.split("/")){if(!seg)throw new Error("Invalid plugin API path.");const d=decodeURIComponent(seg);if(d==="."||d===".."||d.includes("/")||d.includes("\\"))throw new Error("Invalid plugin API path.");}const parsed=new URL(`http://hana.local/${s}`);return raw.split("/").map(x=>encodeURIComponent(decodeURIComponent(x))).join("/")+parsed.search;}
function pluginApiUrl(path){return `${window.location.origin}/api/plugins/${encodeURIComponent(currentPluginId())}/${normalizePluginApiPath(path)}`;}
function pluginApiFetch(path,init={}){const ss=new URLSearchParams(window.location.search).get("pluginSurfaceSession");const h=new Headers(init.headers||{});if(ss)h.set("X-Hana-Plugin-Surface-Session",ss);return fetch(pluginApiUrl(path),{...init,headers:h});}
function hostApiUrl(path){const u=new URL(path,window.location.origin);const t=new URLSearchParams(window.location.search).get("token");if(t)u.searchParams.set("token",t);return u.toString();}
const hana={ready:()=>event("hana.ready"),ui:{resize:(s)=>event("ui.resize",s)},api:{url:pluginApiUrl,fetch:pluginApiFetch},toast:{show:(i)=>request("toast.show",i)},external:{open:(i)=>request("external.open",i)}};
const root=document.getElementById("root");
const surface=root?.dataset.surface||"page";
async function fetchJson(path){const res=await hana.api.fetch(path,{signal:AbortSignal.timeout(8000)});if(!res.ok)throw new Error("HTTP "+res.status);return res.json();}

/* 主题同步（与 v1 一致） */
function parseThemeRgb(v){const raw=String(v||"").trim();let m=raw.match(/^#([0-9a-f]{6})$/i);if(m)return[0,2,4].map(i=>parseInt(m[1].slice(i,i+2),16));m=raw.match(/^#([0-9a-f]{3})$/i);if(m)return[...m[1]].map(x=>parseInt(x+x,16));m=raw.match(/^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/i);return m?[+m[1],+m[2],+m[3]]:null;}
function syncComputedColorMode(){try{const s=getComputedStyle(document.body);const rgb=parseThemeRgb(s.getPropertyValue("--bg"))||parseThemeRgb(s.backgroundColor);if(!rgb)return;const lum=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];const mode=lum<145?"dark":"light";document.documentElement.dataset.colorMode=mode;document.body.dataset.colorMode=mode;}catch{}}
function resolveThemeIntent(t){const raw=typeof t==="string"?t.trim():"";if(raw==="auto")return window.matchMedia?.("(prefers-color-scheme: dark)")?.matches?"midnight":"warm-paper";if(!raw||raw==="inherit")return "";return raw;}
function applyHostTheme(t){const raw=resolveThemeIntent(t);if(!raw)return false;if(document.documentElement.dataset.theme!==raw)document.documentElement.dataset.theme=raw;if(document.body.dataset.hanaTheme!==raw)document.body.dataset.hanaTheme=raw;const tc=document.getElementById("hana-theme-css")||document.querySelector('link[href*="/api/plugins/theme.css"]');if(tc){try{const u=new URL(tc.href,window.location.href);if(u.searchParams.get("theme")!==raw){u.searchParams.set("theme",raw);tc.addEventListener("load",syncComputedColorMode,{once:true});tc.href=u.toString();}}catch{}}requestAnimationFrame(syncComputedColorMode);return true;}
function initHostThemeSync(){const initial=new URLSearchParams(window.location.search).get("hana-theme")||document.body.dataset.hanaTheme||"warm-paper";if(!applyHostTheme(initial))applyHostTheme("warm-paper");try{const hw=window.parent,hd=hw.document,hr=hd.documentElement,media=hw.matchMedia?.("(prefers-color-scheme: dark)");const read=()=>{const a=hr.getAttribute("data-theme")?.trim()||hd.body?.getAttribute("data-theme")?.trim();if(a&&a!=="auto"&&a!=="inherit")return a;const s=hw.localStorage?.getItem("hana-theme")?.trim();if(s&&s!=="auto"&&s!=="inherit")return s;if(initial&&initial!=="auto"&&initial!=="inherit")return initial;return media?.matches?"midnight":"warm-paper";};const sync=()=>applyHostTheme(read());sync();const obs=new MutationObserver(sync);obs.observe(hr,{attributes:true,attributeFilter:["data-theme","class","style"]});if(hd.body)obs.observe(hd.body,{attributes:true,attributeFilter:["data-theme","class","style"]});hw.addEventListener("storage",sync);hw.addEventListener("hana-settings",sync);media?.addEventListener?.("change",sync);const timer=hw.setInterval(sync,500);window.addEventListener("beforeunload",()=>{obs.disconnect();hw.removeEventListener("storage",sync);hw.removeEventListener("hana-settings",sync);media?.removeEventListener?.("change",sync);hw.clearInterval(timer);},{once:true});}catch{}}
initHostThemeSync();
function onHostThemeMessage(evt){if(evt.source!==window.parent)return;const m=evt.data||{};if(m.type!=="hana.host.theme"&&m.type!=="hana.host.context")return;const p=m.payload||{};applyHostTheme(p.resolvedTheme||p.effectiveTheme||p.theme);}
window.addEventListener("message",onHostThemeMessage);
function initAppearancePolling(){const sync=async()=>{try{const a=await fetchJson("/api/appearance");if(a?.theme)applyHostTheme(a.theme);}catch{}};sync();const timer=window.setInterval(sync,1000);window.addEventListener("beforeunload",()=>window.clearInterval(timer),{once:true});}
initAppearancePolling();

/* ── 工具 ── */
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=s=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
const fmtTokens=n=>n==null?"–":(n>=1e6?(n/1e6).toFixed(2)+"M":n>=1e3?(n/1e3).toFixed(1)+"K":String(Math.round(n)));
const fmtCost=v=>v==null?"–":"¥"+Number(v).toFixed(2);
const fmtPct=n=>n==null?"–":Number(n).toFixed(1)+"%";function fmtResetAt(value){if(value==null)return"重置时间未知";let ts=Number(value);if(Number.isFinite(ts)){if(ts<1e12)ts*=1000;}else{ts=Date.parse(value);}if(!Number.isFinite(ts))return"重置时间未知";const ms=Math.max(0,ts-Date.now()),h=Math.floor(ms/36e5),m=Math.floor((ms%36e5)/6e4);return h>0?`${h}h ${m}m 后重置`:`${m}m 后重置`;}function quotaWindowName(item){/* 有准确的中文窗口名（如 5 小时窗口/周窗口）直接用，没有才按秒推算 */if(item?.name&&String(item.name).trim())return String(item.name).trim();const type=String(item?.type||"").trim().toUpperCase();if(type){const zh={CREDIT_LIMIT:"点数额度",TOKENS_LIMIT:"Token 用量限制",REQUESTS_LIMIT:"请求次数限制",TIME_LIMIT:"时间用量限制",DAILY_LIMIT:"日用量限制",WEEKLY_LIMIT:"周用量限制",MONTHLY_LIMIT:"月用量限制",PRIMARY_WINDOW:"5 小时窗口",SECONDARY_WINDOW:"周窗口"};return zh[type]||"额度窗口";}const sec=Number(item?.windowSeconds);if(Number.isFinite(sec)&&sec>0){const h=sec/3600;return Number.isInteger(h)?`${h} 小时窗口`:`${Math.round(sec/60)} 分钟窗口`;}return "额度窗口";}

/* ── SVG 图表 ── */
function axis(vals,{w=640,h=170,axisW=42,plotL=50,plotR=632,top=28,bottom=154,max=null,format=v=>Math.round(v)}={}){const m=max||Math.max(...vals,1)*1.08;let o="";[0,.25,.5,.75,1].forEach(p=>{const v=m*(1-p),y=top+p*(bottom-top);o+=`<line class="grid-line" x1="${plotL}" y1="${y}" x2="${plotR}" y2="${y}"/><text class="axis-text" x="${axisW-6}" y="${y+3}" text-anchor="end">${format(v)}</text>`});return o;}
function xAxis(n,o={}){const pl=o.plotL||50,pr=o.plotR||632,bottom=o.bottom||154,h=o.h||170,labels=o.labels,ticks=Math.min(o.ticks||5,Math.max(1,n)),step=(pr-pl)/(n-1||1);let out=`<line class="grid-line" x1="${pl}" y1="${bottom}" x2="${pr}" y2="${bottom}"/>`;for(let t=0;t<ticks;t++){const idx=t===ticks-1?n-1:Math.round((n-1)*t/(ticks-1));const x=pl+idx*step;const tx=t===0?x+12:t===ticks-1?x-12:x;const anchor=t===0?"start":t===ticks-1?"end":"middle";const lab=(typeof labels==="function")?labels(idx):(Array.isArray(labels)?(labels[idx]??idx+1):idx+1);out+=`<line class="grid-line" x1="${x}" y1="${bottom}" x2="${x}" y2="${bottom+4}"/><text class="axis-text" x="${tx}" y="${bottom+14}" text-anchor="${anchor}">${lab}</text>`}return out;}
function line(vals,opt={}){const w=opt.w||640,ph=opt.h||170,h=ph+18,axisW=42,pad=8,pl=axisW+pad,pr=w-pad,top=28,bottom=ph-8,max=opt.yMax||Math.max(...vals,1)*1.08,step=(pr-pl)/((vals.length||1)-1),Y=v=>bottom-(v/max)*(bottom-top);const pts=vals.map((v,i)=>[pl+i*step,Y(v)]),path=pts.map((p,i)=>(i?"L":"M")+p[0].toFixed(1)+","+p[1].toFixed(1)).join(""),area=path+` L${pl},${bottom} Z`;return `<svg viewBox="0 0 ${w} ${h}">${axis(vals,{w,h:ph,axisW,plotL:pl,plotR:pr,top,bottom,max,format:opt.format||fmtTokens})}<path class="si-area" d="${area}" fill="${opt.fill||"rgba(141,187,210,.10)"}"/><path class="si-line" pathLength="1" d="${path}" fill="none" stroke="${opt.stroke||"var(--accent)"}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>${xAxis(vals.length,{plotL:pl,plotR:pr,bottom,h,labels:opt.xLabels,format:opt.xFormat,ticks:opt.xticks})}</svg>`;}
function bars(vals,opt={}){const w=opt.w||640,ph=opt.h||170,h=ph+18,axisW=42,pad=8,pl=axisW+pad,pr=w-pad,top=28,bottom=ph-8,max=opt.yMax||Math.max(...vals,1)*1.08,slot=(pr-pl)/(vals.length||1),bw=Math.max(3,Math.min(12,slot*.62));let s="";vals.forEach((v,i)=>{const bh=Math.max((v/max)*(bottom-top),.5),x=pl+i*slot+(slot-bw)/2,y=bottom-bh;s+=`<rect class="si-bar" x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${bw.toFixed(1)}" height="${bh.toFixed(1)}" rx="6" fill="${opt.fill||"rgba(141,187,210,.58)"}" style="animation-delay:${(i*.018).toFixed(2)}s"></rect>`;});return `<svg viewBox="0 0 ${w} ${h}">${axis(vals,{w,h:ph,axisW,plotL:pl,plotR:pr,top,bottom,max,format:opt.format||fmtTokens})}${s}${xAxis(vals.length,{plotL:pl,plotR:pr,bottom,h,labels:opt.xLabels,ticks:opt.xticks})}</svg>`;}
function stack(rows,opt={}){const vals=rows.map(r=>r.a+r.b+r.c),w=opt.w||640,ph=opt.h||170,h=ph+18,axisW=42,pad=8,pl=axisW+pad,pr=w-pad,top=12,bottom=ph-8,max=Math.max(...vals,1)*1.08,slot=(pr-pl)/(rows.length||1),bw=Math.max(3,Math.min(12,slot*.62)),colors=["rgba(141,187,210,.72)","rgba(141,187,210,.32)","rgba(213,168,106,.62)"];let s="";rows.forEach((r,i)=>{let yb=bottom;["a","b","c"].forEach((k,ki)=>{const v=r[k]||0,bh=(v/max)*(bottom-top),x=pl+i*slot+(slot-bw)/2,y=yb-bh;s+=`<rect class="si-bar" x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${bw.toFixed(1)}" height="${bh.toFixed(1)}" rx="6" fill="${colors[ki]}" style="animation-delay:${(i*.015+ki*.03).toFixed(2)}s"></rect>`;yb=y;});});return `<svg viewBox="0 0 ${w} ${h}">${axis(vals,{w,h:ph,axisW,plotL:pl,plotR:pr,top,bottom,max,format:fmtTokens})}${s}${xAxis(rows.length,{plotL:pl,plotR:pr,bottom,h,labels:opt.xLabels,ticks:opt.xticks})}</svg>`;}
function donutChart(segs,{size=148,r=52,sw=15,center="–",sub=""}={}){const C=2*Math.PI*r,cx=size/2,cy=size/2,total=segs.reduce((s,x)=>s+(x.v||0),0)||1;let off=0,arcs="";segs.forEach(seg=>{const len=(seg.v/total)*C;arcs+=`<circle class="si-sect" cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${seg.color}" stroke-width="${sw}" stroke-dasharray="${len.toFixed(2)} ${C.toFixed(2)}" stroke-dashoffset="${(-off+C).toFixed(2)}" style="--to:${(-off).toFixed(2)};animation-delay:${(off/C*.12).toFixed(2)}s"></circle>`;off+=len;});return `<svg viewBox="0 0 ${size} ${size}" style="transform:rotate(-90deg)"><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="color-mix(in srgb,var(--text) 7%,transparent)" stroke-width="${sw}"/>${arcs}</svg><div class="ring-core" style="position:absolute;inset:0;display:grid;place-content:center"><strong>${esc(center)}</strong><span>${esc(sub)}</span></div>`;}
function heatHtml(days){const n=days&&days.length?days.length:0;if(!n)return `<div class="empty">暂无每日数据</div>`;return days.map(d=>`<i class="l${d.l}" data-day="${d.d}" style="--heat-delay:${Math.round(Math.random()*420)}ms"></i>`).join("");}

